import { Component, OnInit } from '@angular/core';
import { FormArray, FormBuilder, FormGroup } from '@angular/forms';

@Component({
  selector: 'app-notes',
  templateUrl: './notes.component.html',
  styleUrls: ['./notes.component.css'],
})
export class NotesComponent implements OnInit {
  public formGroup!: FormGroup;
  public formGroupStorage: any;
  public isPaidByCustomer: boolean[] = [];

  constructor(private _formBuilder: FormBuilder) {}

  ngOnInit(): void {
    this.formGroupStorage = JSON.parse(localStorage.getItem('client') ?? '{}');
    this._buildForm();
  }

  private _buildForm() {
    this.formGroup = this._formBuilder.group({
      customerDetails: this._formBuilder.array(
        this.formGroupStorage?.customerDetails?.length
          ? (this.formGroupStorage.customerDetails ?? []).map(
              (details: any, index: number) => {
                this.isPaidByCustomer[index] = details.isPaid;
                return this.getCustomerDetails(details);
              },
            )
          : [this.getCustomerDetails()],
      ),
    });
  }

  get customerDetails(): FormArray<FormGroup> {
    return this.formGroup.get('customerDetails') as FormArray<FormGroup>;
  }

  public items(index: number): FormArray<FormGroup> {
    return this.customerDetails.at(index).get('items') as FormArray<FormGroup>;
  }

  public getCustomerDetails(value?: any): FormGroup {
    return this._formBuilder.group({
      name: [value?.name ?? ''],
      isPaid: [value?.isPaid ?? false],
      items: this._formBuilder.array(
        value?.items?.length
          ? (value?.items || []).map((item: any) => this.getItems(item))
          : [this.getItems()],
      ),
    });
  }

  public getItems(item?: any): FormGroup {
    return this._formBuilder.group({
      itemName: [item?.itemName ?? ''],
      itemCount: [item?.itemCount ?? 0],
    });
  }

  public addCustomer(): void {
    this.customerDetails.push(this.getCustomerDetails());
  }

  public paidByCustomer(bill: string, index: number): void {
    this.isPaidByCustomer[index] = bill === 'paid';
    const getIsPaid = this.customerDetails.at(index).get('isPaid');
    getIsPaid?.patchValue(bill === 'paid');
    localStorage.setItem('client', JSON.stringify(this.formGroup.value));
  }

  public addItem(index: number): void {
    const value = this.customerDetails
      .at(index)
      .get('items') as FormArray<FormGroup>;
    value.push(this.getItems());
  }

  public onDeleteItem(cusomerIndex: number, itemIndex: number): void {
    this.items(cusomerIndex)?.removeAt(itemIndex);
  }

  public onSubmit(): void {
    localStorage.setItem('client', JSON.stringify(this.formGroup.value));
  }

  public onClickEditBtn(isPaid: boolean, index: number): void {
    this.isPaidByCustomer[index] = !isPaid;
  }
}
<form class="pt-4" [formGroup]="formGroup" (ngSubmit)="onSubmit()">
  <div formArrayName="customerDetails" class="customer">
    <div
      class="card payment-card"
      *ngFor="let customer of customerDetails.controls; let i = index"
      [formGroupName]="i"
    >
      <div class="card-header payment-card__header">
        <div class="row">
          <div class="col-6">
            <input
              type="text"
              class="form-control"
              formControlName="name"
              placeholder="Customer name"
            />
          </div>
          <div class="col-6 d-flex align-items-center justify-content-end">
            <span
              *ngIf="customer.get('isPaid')?.value"
              class="payment-card__status payment-card__status--paid"
              >PAID</span
            >
            <span
              *ngIf="!customer.get('isPaid')?.value"
              class="payment-card__status payment-card__status--unpaid"
              >UNPAID</span
            >
          </div>
        </div>
      </div>

      <div
        [class.disabled-customer-bill]="isPaidByCustomer[i]"
        formArrayName="items"
        class="card-body payment-card__body d-flex flex-column gap-3"
        [class.scroll-max-height]="items(i).controls.length > 2"
      >
        <div
          class="row"
          *ngFor="let item of items(i).controls; let j = index"
          [formGroupName]="j"
        >
          <div class="col-5">
            <label for="items" class="form-label">Items</label>
            <input
              type="text"
              class="form-control"
              formControlName="itemName"
              placeholder="Item name"
            />
          </div>
          <div class="col-5">
            <label for="items" class="form-label">No. of items</label>

            <input
              class="form-control"
              type="number"
              formControlName="itemCount"
              name="itemCount"
              id="itemCount"
              placeholder="Quantity"
            />
          </div>
          <div class="col-2 d-flex align-items-end">
            <button
              type="button"
              class="delete-btn"
              (click)="onDeleteItem(i, j)"
            >
              <i class="bi bi-trash-fill"></i>
            </button>
          </div>
        </div>
      </div>

      <div class="row p-2">
        <div class="col">
          <button
            class="mt-4 border-2 rounded-2"
            style="padding: 2px 10px; background-color: transparent"
            (click)="addItem(i)"
          >
            + Add Item
          </button>
        </div>
      </div>

      <div class="row p-2">
        <div class="col">
          <button
            *ngIf="!isPaidByCustomer[i]"
            class="payment-card__button payment-card--paid"
            (click)="paidByCustomer('paid', i)"
          >
            Paid
          </button>
          <button
            *ngIf="isPaidByCustomer[i]"
            class=""
            (click)="onClickEditBtn(customer.get('isPaid')?.value, i)"
          >
            Edit
          </button>
        </div>
      </div>
    </div>
  </div>
  <button
    class="mt-4 border-2 rounded-2"
    style="padding: 2px 10px; background-color: transparent"
    (click)="addCustomer()"
  >
    +
  </button>
</form>
